200	        Set<Long> chosen = Set.copyOf(personIds);
201	        List<Person> picked = people.findBySheetIdOrderByIdAsc(sheetId).stream()
202	                .filter(p -> chosen.contains(p.getId())).toList();
203	        if (picked.size() != chosen.size()) {
204	            throw new PersonNotFoundException();
205	        }
206	        return picked.stream().map(p -> update(sheetId, user, p.getId(), p.getVersion(), p.getName(), grade, from,
207	                p.getTerms(), p.getContact())).toList();
