1	package net.officefloor.hq.app.person;
2	
3	import jakarta.servlet.http.HttpServletRequest;
4	import jakarta.validation.Valid;
5	import jakarta.validation.constraints.Min;
6	import jakarta.validation.constraints.NotBlank;
7	import jakarta.validation.constraints.NotNull;
8	import jakarta.validation.constraints.Pattern;
9	import jakarta.validation.constraints.Size;
10	import java.time.LocalDate;
11	import java.util.List;
12	import java.util.Map;
13	import java.util.Set;
14	import java.util.stream.Collectors;
15	import net.officefloor.hq.app.history.AsOf;
16	import org.springframework.format.annotation.DateTimeFormat;
17	import org.springframework.http.HttpStatus;
18	import org.springframework.http.ResponseEntity;
19	import org.springframework.orm.ObjectOptimisticLockingFailureException;
20	import org.springframework.validation.annotation.Validated;
21	import org.springframework.web.bind.annotation.ExceptionHandler;
22	import org.springframework.web.bind.annotation.GetMapping;
23	import org.springframework.web.bind.annotation.PathVariable;
24	import org.springframework.web.bind.annotation.PostMapping;
25	import org.springframework.web.bind.annotation.PutMapping;
26	import org.springframework.web.bind.annotation.RequestBody;
27	import org.springframework.web.bind.annotation.RequestHeader;
28	import org.springframework.web.bind.annotation.RequestMapping;
29	import org.springframework.web.bind.annotation.ResponseStatus;
30	import org.springframework.web.bind.annotation.RestController;
31	import org.springframework.web.server.ResponseStatusException;
32	
33	/** The people on a sheet. The signed-in user's name comes in the X-User header. */
34	@RestController
35	@Validated
36	@RequestMapping("/api/sheets/{sheetId}/people")
37	public class PersonController {
38	
39	    /** A person as the screen shows it, with how many statements were taken of them and the last one's
40	     *  due-total (n/a when it was) and date; none of either before their first statement; and the ids
41	     *  of their patrons. Their grade is the one in force on the sheet's today; grades lists every grade
42	     *  they were given, each with its from-date (YYYY-MM-DD, none for the first); watched says whether
43	     *  the signed-in user watches them. */
44	    public record PersonView(long id, String name, String grade, List<GradeView> grades, long version, int statementCount,
45	            String statedTotal, String statementDate, boolean retired, String retiredFrom,
46	            boolean held, List<HoldView> holds, List<Long> patronIds, boolean watched, Integer terms, String contact,
47	            List<String> aliases) {
48	
49	        public static PersonView of(Person person, LocalDate today, List<Statement> statements, List<Long> patronIds,
50	                boolean watched) {
51	            Statement last = statements.isEmpty() ? null : statements.get(statements.size() - 1);
52	            return new PersonView(person.getId(), person.getName(), person.gradeOn(today),
53	                    person.getGrades().stream().map(GradeView::of).toList(), person.getVersion(),
54	                    statements.size(),
55	                    last == null ? null : last.getDueTotal() == null ? "n/a" : last.getDueTotal().toPlainString(),
56	                    last == null ? null : last.getTakenOn().toString(),
57	                    person.isRetired(), person.getRetiredFrom() == null ? null : person.getRetiredFrom().toString(),
58	                    person.isHeld(), person.getHolds().stream().map(HoldView::of).toList(), patronIds,
59	                    watched, person.getTerms(), person.getContact(), person.getAliases());
60	        }
61	    }
62	
63	    /** A grade a person was given and the date it applies from; none for the beginning of time. */
64	    public record GradeView(String grade, String from) {
65	
66	        static GradeView of(PersonGrade grade) {
67	            return new GradeView(grade.getGrade(), grade.getFromDate() == null ? null : grade.getFromDate().toString());
68	        }
69	    }
70	
71	    /** A hold on a person: its from-date (none for the beginning of time) and its to-date (none while it
72	     *  has no end), each YYYY-MM-DD. */
73	    public record HoldView(String from, String to) {
74	
75	        static HoldView of(PersonHold hold) {
76	            return new HoldView(hold.getFromDate() == null ? null : hold.getFromDate().toString(),
77	                    hold.getToDate() == null ? null : hold.getToDate().toString());
78	        }
79	    }
80	
81	    /** The dates a hold covers: from a date (none takes the sheet's today) to a date (none: no end). */
82	    public record HoldRequest(LocalDate from, LocalDate to) {
83	    }
84	
85	    public record PersonRequest(
86	            @NotBlank @Size(max = 200) String name,
87	            @NotNull @Pattern(regexp = "[ABC]") String grade,
88	            @Min(0) Integer terms,
89	            @Size(max = 200) String contact) {
90	    }
91	
92	    /** A person's new name and grade, the date the grade applies from (none: the sheet's today, or
93	     *  nothing recorded when the grade is the one in force then), with the version of the person the
94	     *  editor loaded. */
95	    public record PersonUpdate(
96	            @NotBlank @Size(max = 200) String name,
97	            @NotNull @Pattern(regexp = "[ABC]") String grade,
98	            LocalDate gradeFrom,
99	            @Min(0) Integer terms,
100	            @Size(max = 200) String contact,
101	            @NotNull Long version) {
102	    }
103	
104	    /** The people to give a grade together, the grade, and the date it applies from (none: the sheet's
105	     *  today). */
106	    public record BulkGradeRequest(
107	            @NotNull @Size(min = 1, max = 10000) List<@NotNull Long> personIds,
108	            @NotNull @Pattern(regexp = "[ABC]") String grade,
109	            LocalDate from) {
110	    }
111	
112	    /** How many a bulk grade changed, and the people it changed. */
113	    public record BulkGradeView(int graded, List<PersonView> people) {
114	    }
115	
116	    /** The person to name as a patron. */
117	    public record PatronRequest(@NotNull Long patronId) {
118	    }
119	
120	    /** An alias to give a person; a blank one is refused with the reason. */
121	    public record AliasRequest(String alias) {
122	    }
123	
124	    /** Whether the signed-in user is to watch the person. */
125	    public record WatchRequest(@NotNull Boolean watched) {
126	    }
127	
128	    /** The date a person is retired from; none takes the sheet's today. */
129	    public record RetireRequest(LocalDate from) {
130	    }
131	
132	    private final PersonService service;
133	    private final AsOf asOf;
134	
135	    public PersonController(PersonService service, AsOf asOf) {
136	        this.service = service;
137	        this.asOf = asOf;
138	    }
139	
140	    /** The sheet's people in the order they were added; as they stood at the end of a date when the screen
141	     *  views the sheet as of one. */
142	    @GetMapping
143	    public List<PersonView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
144	            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
145	            @RequestHeader(value = AsOf.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
146	        String id = sheetId.trim();
147	        Map<Long, List<Statement>> statements = asOf == null ? service.statements(id)
148	                : this.asOf.statements(id, asOf).stream().collect(Collectors.groupingBy(Statement::getPersonId));
149	        Map<Long, List<Long>> patrons = asOf == null ? service.patrons(id)
150	                : this.asOf.patrons(id, asOf).stream().collect(Collectors.groupingBy(Patron::getPersonId,
151	                        Collectors.mapping(Patron::getPatronId, Collectors.toList())));
152	        List<Person> people = asOf == null ? service.list(id) : this.asOf.people(id, asOf);
153	        LocalDate today = asOf == null ? service.today(id) : this.asOf.today(id, asOf);
154	        Set<Long> watched = asOf == null ? service.watchedBy(id, user.trim())
155	                : this.asOf.watches(id, asOf).stream().filter(w -> w.getUser().equals(user.trim()))
156	                        .map(Watch::getPersonId).collect(Collectors.toSet());
157	        return people.stream()
158	                .map(p -> PersonView.of(p, today, statements.getOrDefault(p.getId(), List.of()),
159	                        patrons.getOrDefault(p.getId(), List.of()), watched.contains(p.getId())))
160	                .toList();
161	    }
162	
163	    /** Add a person to the sheet. */
164	    @PostMapping
165	    public PersonView add(@PathVariable @NotBlank @Size(max = 200) String sheetId,
166	            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
167	            @RequestBody @Valid PersonRequest request) {
168	        Person added = service.add(sheetId.trim(), user.trim(), request.name(), request.grade(), request.terms(),
169	                request.contact());
170	        return PersonView.of(added, service.today(sheetId.trim()), List.of(), List.of(), false);
171	    }
172	
173	    /** Change a person's name, and give them a grade from a date. */
174	    @PutMapping("/{personId}")
175	    public PersonView update(@PathVariable @NotBlank @Size(max = 200) String sheetId,
176	            @PathVariable long personId,
177	            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
178	            @RequestBody @Valid PersonUpdate request) {
179	        try {
180	            Person updated = service.update(sheetId.trim(), user.trim(), personId, request.version(),
181	                    request.name(), request.grade(), request.gradeFrom(), request.terms(), request.contact());
182	            return view(updated, user.trim());
183	        } catch (ObjectOptimisticLockingFailureException e) {
184	            // saved by someone else between the version check and the write
185	            throw new PersonVersionConflictException(service.current(sheetId.trim(), personId));
186	        }
187	    }
188	
189	    /** Give the chosen people a grade from a date together, in list order. */
190	    @PostMapping("/bulk-grade")
191	    public BulkGradeView bulkGrade(@PathVariable @NotBlank @Size(max = 200) String sheetId,
192	            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
193	            @RequestBody @Valid BulkGradeRequest request) {
194	        try {
195	            List<Person> graded = service.bulkGrade(sheetId.trim(), user.trim(), request.personIds(), request.grade(),
196	                    request.from());
197	            return new BulkGradeView(graded.size(), graded.stream().map(p -> view(p, user.trim())).toList());
198	        } catch (ObjectOptimisticLockingFailureException e) {
199	            // one of them was saved by someone else at the same moment
200	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Someone else changed one of them; try again.");
201	        }
202	    }
203	
204	    /** Retire a person from a date. */
205	    @PostMapping("/{personId}/retire")
206	    public PersonView retire(@PathVariable @NotBlank @Size(max = 200) String sheetId,
207	            @PathVariable long personId,
208	            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
209	            @RequestBody RetireRequest request) {
210	        Person retired = service.retire(sheetId.trim(), user.trim(), personId, request.from());
